mapper.select:
SELECT DATE(#{dayStart}) AS stat_date,
/* 所有未逻辑删除的工单。 */ (SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0) AS ticket_count,
/* 已关闭工单总量；RESOLVED 与 CLOSED 在业务上分别表示“已解决”和“已归档”。 */ (SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND t.status = 'CLOSED') AS closed_count,
/* 当日创建的会话需独立统计，不能通过 ticket JOIN，否则无工单会话会被遗漏。 */ (SELECT COUNT(1) FROM conversation_session s WHERE s.created_at >= #{dayStart} AND s.created_at < #{dayEnd}) AS today_session_count,
(SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND t.created_at >= #{dayStart} AND t.created_at < #{dayEnd}) AS today_ticket_count,
(SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND t.review_status = 'PENDING_REVIEW' AND t.status = 'PENDING_REVIEW') AS pending_review_ticket_count,
(SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND t.review_status = 'APPROVED' AND t.status = 'WAITING_ASSIGN') AS waiting_assign_ticket_count,
(SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND t.status = 'PROCESSING') AS processing_ticket_count,
/* 截止时间在未来 30 分钟内，且当前工单仍需要首响或解决的数量。 */ (SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND ( (t.status IN ('ASSIGNED', 'PROCESSING') AND t.first_responded_at IS NULL AND t.first_response_deadline >= #{now} AND t.first_response_deadline <= DATE_ADD(#{now}, INTERVAL 30 MINUTE)) OR (t.status NOT IN ('RESOLVED', 'CLOSED', 'REJECTED') AND t.resolve_deadline >= #{now} AND t.resolve_deadline <= DATE_ADD(#{now}, INTERVAL 30 MINUTE)) )) AS risk_ticket_count,
(SELECT COUNT(1) FROM ticket t WHERE t.deleted = 0 AND ( (t.status IN ('ASSIGNED', 'PROCESSING') AND t.first_responded_at IS NULL AND t.first_response_deadline < #{now}) OR (t.status NOT IN ('RESOLVED', 'CLOSED', 'REJECTED') AND t.resolve_deadline < #{now}) )) AS overdue_ticket_count,
/* 用秒计算再除以 60，保留分钟的小数精度。 */ (SELECT COALESCE(ROUND(AVG(TIMESTAMPDIFF(SECOND, t.created_at, t.first_responded_at)) / 60, 2), 0) FROM ticket t WHERE t.deleted = 0 AND t.first_responded_at IS NOT NULL) AS avg_first_response_minutes,
/* 当前没有“AI 独立解决”标记，暂以含 AI 摘要的已结案工单占所有已结案工单的比例作为辅助解决覆盖率。 */ (SELECT COALESCE(ROUND( SUM(CASE WHEN t.ai_summary IS NOT NULL AND t.ai_summary != '' THEN 1 ELSE 0 END) / NULLIF(COUNT(1), 0), 4), 0) FROM ticket t WHERE t.deleted = 0 AND t.status IN ('RESOLVED', 'CLOSED')) AS ai_resolve_rate
